def positive_mean(values):
    total = 0.0
    count = 0
    for value in values:
        if value <= 0:
            continue
        total += value
        count += 1
    if count == 0:
        raise ValueError("No positive observations")
    return total / count


print(positive_mean([-2, 0, 3, 5]))  # 4.0, illustrative
print(-7 // 2)  # -4

import math


def finite_mean(values: list[float]) -> float:
    if not values:
        raise ValueError("At least one observation required")
    if any(not math.isfinite(x) for x in values):
        raise ValueError("Finite observations required")
    return math.fsum(x / len(values) for x in values)


print(finite_mean([1.0, 2.0, 3.0]))  # 2.0
