import math


class Centerer:
    def __init__(self):
        self.mean_ = None

    def fit(self, X):
        if not X or not X[0]:
            raise ValueError("Need nonempty 2-D training data")
        n_rows = len(X)
        n_cols = len(X[0])
        sums = [0.0] * n_cols
        for row in X:
            if len(row) != n_cols:
                raise ValueError("All rows must have equal feature count")
            for j in range(n_cols):
                val = float(row[j])
                if not math.isfinite(val):
                    raise ValueError("Finite training values required")
                sums[j] += val
        means = []
        for j in range(n_cols):
            means.append(sums[j] / n_rows)
        self.mean_ = tuple(means)
        return self

    def transform(self, X):
        if self.mean_ is None:
            raise RuntimeError("Call fit before transform")
        n_cols = len(self.mean_)
        output = []
        for row in X:
            if len(row) != n_cols:
                raise ValueError("Feature count mismatch")
            new_row = []
            for j in range(n_cols):
                val = float(row[j])
                if not math.isfinite(val):
                    raise ValueError("Finite values required")
                new_row.append(val - self.mean_[j])
            output.append(new_row)
        return output


