test_X = [[5.0, 30.0]]
center = Centerer().fit(train_X)
print("Learned train means:", center.mean_)
print("Centered test batch:", center.transform(test_X))
print("Original test_X untouched:", test_X)

from itertools import islice


def batches(iterable, size, *, drop_last=False):
    if not isinstance(size, int) or isinstance(size, bool) or size <= 0:
        raise ValueError("Positive integer size required")
    source = iter(iterable)
    while True:
        batch = tuple(islice(source, size))
        if not batch:
            return
        if len(batch) < size and drop_last:
            return
        yield batch


