# Cardinality (many_to_one), Indicator এবং source_row ক্রম যাচাইসহ নিরাপদ Lookup Join!
def safe_many_to_one_join(left_rows, lookup_rows, *, on_key):
    # ১) ডান পাশের Lookup টেবিলে প্রতিটি Key অনন্য (Unique) ও Non-null হতেই হবে!
    lookup_map = {}
    for rec in lookup_rows:
        key = rec[on_key]
        if key is None:
            raise ValueError("Null join key in lookup table")
        if key in lookup_map:
            raise ValueError("Cardinality violation (many_to_one): duplicate lookup key " + str(key))
        lookup_map[key] = rec

    # ২) বাম পাশের প্রতিটি সারি মূল source_row ক্রমে যুক্ত করা + indicator রাখা
    joined = []
    for row in left_rows:
        key = row[on_key]
        if key is None:
            raise ValueError("Null join key in left table")
        merged = dict(row)
        if key in lookup_map:
            for k, v in lookup_map[key].items():
                if k != on_key:
                    merged[k] = v
            merged["_merge"] = "both"
        else:
            merged["_merge"] = "left_only"
        joined.append(merged)
    return joined


rows = [
    {"source_row": 0, "city": "A"},
    {"source_row": 1, "city": "B"},
    {"source_row": 2, "city": "A"},
]
lookup = [{"city": "A", "code": 10}, {"city": "B", "code": 20}]
result = safe_many_to_one_join(rows, lookup, on_key="city")

assert len(result) == len(rows)
for i in range(len(rows)):
    assert result[i]["source_row"] == rows[i]["source_row"]
    assert result[i]["_merge"] == "both"
print("Joined row count:", len(result), "| Codes:", [result[0]["code"], result[1]["code"], result[2]["code"]])

# groupby(..., dropna=False)-এ 'size' (মোট Row) বনাম 'count' (Non-null মান)-এর পার্থক্য!
records = [
    {"group": "A", "value": 1.0},
