print("Group A -> size (total rows):", summary["A"]["size"], "| count (non-null):", summary["A"]["count"])
print("Group None -> size:", summary[None]["size"], "| count:", summary[None]["count"])

import unittest
import math


def safe_average(xs):
    if not xs or any(not math.isfinite(x) for x in xs):
        raise ValueError("Need finite observations")
    return math.fsum(x / len(xs) for x in xs)


class AverageTests(unittest.TestCase):
    def test_known_result(self):
        self.assertAlmostEqual(safe_average([1.0, 2.0, 3.0]), 2.0)

    def test_empty_rejected(self):
        with self.assertRaises(ValueError):
            safe_average([])


suite = unittest.defaultTestLoader.loadTestsFromTestCase(AverageTests)
result = unittest.TestResult()
suite.run(result)
assert result.wasSuccessful()
