def numeric_matrix(
    frame: pd.DataFrame, columns: tuple[str, ...] = NUMERIC
) -> np.ndarray:
    if not columns or len(set(columns)) != len(columns):
        raise ValueError("Need unique ordered feature names")
    matrix = np.array(
        frame.loc[:, list(columns)].to_numpy(dtype=np.float64, na_value=np.nan),
        dtype=np.float64,
        copy=True,
        order="C",
    )
    if matrix.ndim != 2 or matrix.shape[1] != len(columns) or np.isinf(matrix).any():
        raise ValueError("Invalid numeric matrix")
    # Missing numeric values remain NaN for this audit; no global imputation.
    return matrix


@dataclass
class OnlineMoments:
    count: int = 0
    mean: float = 0.0
    m2: float = 0.0

    def update(self, values: np.ndarray) -> None:
        values = np.asarray(values, dtype=np.float64)
        if values.ndim != 1 or not np.isfinite(values).all():
            raise ValueError("Expected a finite one-dimensional observed batch")
        if values.size == 0:
            return
        batch_count = int(values.size)
        batch_mean = float(values.mean())
        centered = values - batch_mean
        batch_m2 = float(centered @ centered)
        total = self.count + batch_count
        delta = batch_mean - self.mean
        new_mean = self.mean + delta * (batch_count / total)
        new_m2 = self.m2 + batch_m2 + delta * delta * (self.count / total) * batch_count
        if not np.isfinite([new_mean, new_m2]).all():
            raise ValueError("Moment calculation overflow; state was not updated")
        self.count, self.mean, self.m2 = total, new_mean, new_m2

    def summary(self) -> dict:
        return {
            "observed": self.count,
            "mean": self.mean if self.count else None,
            "population_variance": self.m2 / self.count if self.count else None,
        }


def attach_audit_counts(rows: pd.DataFrame, lookup: pd.DataFrame) -> pd.DataFrame:
    if (
        rows["source_row"].duplicated().any()
        or rows["workclass"].isna().any()
        or lookup["workclass"].isna().any()
    ):
        raise ValueError(
            "Need unique source positions and explicit missing-key sentinel"
        )
    joined = rows.merge(
        lookup,
        on="workclass",
        how="left",
        sort=False,
        validate="many_to_one",
        indicator=True,
    )
    if (
        len(joined) != len(rows)
        or joined["source_row"].tolist() != rows["source_row"].tolist()
        or not joined["_merge"].eq("both").all()
    ):
        raise ValueError("Merge changed row identity or lookup coverage")
    return joined.drop(columns="_merge")

import math


def mean_absolute_error(labels, predictions):
    labels, predictions = list(labels), list(predictions)
    if not labels or len(labels) != len(predictions):
        raise ValueError("Expected equal, nonempty sequences")
    values = labels + predictions
    if not all(math.isfinite(value) for value in values):
        raise ValueError("Inputs must be finite")
    # Validate before zip: zip would silently discard unmatched rows.
    absolute_errors = [abs(y - p) for y, p in zip(labels, predictions)]
    return math.fsum(absolute_errors) / len(labels)


print(mean_absolute_error([1, 4], [2, 2]))

from dataclasses import dataclass
from itertools import islice
import math


@dataclass(frozen=True)
class AuditConfig:
    numeric_cols: tuple[str, ...] = ("age", "hours")
    expected_labels: tuple[str, ...] = ("<=50K", ">50K")


class OnlineMoments:
    def __init__(self):
        self.count = 0
        self.mean = 0.0
        self.m2 = 0.0

    def update_batch(self, values):
        if not values:
            return
        b_n = len(values)
        b_mean = math.fsum(values) / b_n
        b_m2 = 0.0
        for v in values:
            d = v - b_mean
            b_m2 += d * d
        total_n = self.count + b_n
        delta = b_mean - self.mean
        new_mean = self.mean + delta * (b_n / total_n)
        new_m2 = self.m2 + b_m2 + (delta * delta) * (self.count * b_n / total_n)
        if not (math.isfinite(new_mean) and math.isfinite(new_m2)):
            raise ValueError("Overflow in moment update")
        self.count = total_n
        self.mean = new_mean
        self.m2 = new_m2

    def pop_variance(self):
        if self.count == 0:
            return None
        return self.m2 / self.count


def batches(iterable, size):
    if isinstance(size, bool) or not isinstance(size, int) or size <= 0:
        raise ValueError("Positive int chunk_size required")

    def _gen():
        src = iter(iterable)
        while True:
            chunk = tuple(islice(src, size))
            if not chunk:
                return
            yield chunk

    return _gen()


def run_mini_audit(records, chunk_size, cfg):
    moments = {}
    for col in cfg.numeric_cols:
        moments[col] = OnlineMoments()
    label_counts = {}
    missing_counts = {}
    total_rows = 0

    for chunk in batches(records, chunk_size):
        col_bufs = {}
        for col in cfg.numeric_cols:
            col_bufs[col] = []
        for row in chunk:
            lbl = row["income"].strip()
            if lbl not in cfg.expected_labels:
                raise ValueError("Unexpected label: " + lbl)
            label_counts[lbl] = label_counts.get(lbl, 0) + 1
            for col in cfg.numeric_cols:
                val = row[col]
                if val is None:
                    missing_counts[col] = missing_counts.get(col, 0) + 1
                else:
                    num = float(val)
                    if not math.isfinite(num):
                        raise ValueError("Non-finite value in " + col)
                    col_bufs[col].append(num)
            total_rows += 1
        for col in cfg.numeric_cols:
            moments[col].update_batch(col_bufs[col])

    return {
        "rows": total_rows,
        "labels": label_counts,
        "missing": missing_counts,
        "age_mean": moments["age"].mean,
        "age_var": moments["age"].pop_variance(),
    }


sample_data = [
    {"age": 25, "hours": 40, "income": "<=50K"},
    {"age": 38, "hours": 50, "income": ">50K"},
    {"age": None, "hours": 35, "income": "<=50K"},
    {"age": 52, "hours": 45, "income": ">50K"},
    {"age": 31, "hours": 40, "income": "<=50K"},
    {"age": 44, "hours": None, "income": ">50K"},
    {"age": 29, "hours": 38, "income": "<=50K"},
]
cfg = AuditConfig()
r2 = run_mini_audit(sample_data, 2, cfg)
r3 = run_mini_audit(sample_data, 3, cfg)
r5 = run_mini_audit(sample_data, 5, cfg)

# Chunk-size independence invariant across prime/non-prime chunk sizes!
assert r2["rows"] == r3["rows"] == r5["rows"] == 7
assert r2["labels"] == r3["labels"] == r5["labels"]
assert r2["missing"] == r3["missing"] == r5["missing"]
assert math.isclose(r2["age_mean"], r5["age_mean"], rel_tol=1e-12)
assert math.isclose(r2["age_var"], r5["age_var"], rel_tol=1e-12)
print("Chunk-size independence PASSED (chunk_size=2, 3, 5)!")
print("Rows:", r2["rows"], "| Labels:", r2["labels"], "| Missing:", r2["missing"])
print("Age mean:", round(r2["age_mean"], 4), "| Age pop_var:", round(r2["age_var"], 4))

